var NowUtilsUpdateSetMigrator = Class.create();
NowUtilsUpdateSetMigrator.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    migrateUpdateSet: function() {


        var localUpdateSet = 'dc7bf827833a8310a5875160ceaad341';

        var TARGET_INSTANCE_URL = 'https://dev438921.service-now.com';
        var TARGET_USERNAME = 'Update Set Deployer';
        var TARGET_PASSWORD = '%2#-V8*CO1p_Iy$={@Ntq8roYb_%PR3r}n;[sS<LqxnYEP-,%XlvsV+Bx(WXn&>5fF)L1iKrvV=!MlX[)_q>8rLSY_,S#0@eBdXP';

        var TARGET_API_PATH =
            '/api/1351433/update_set_deployer/import';

        var payload = {};
        var requestData = new GlideRecord('sys_update_set');

        if (requestData.get(localUpdateSet)) {
            var fields = requestData.getFields().iterator();

            while (fields.hasNext()) {
                var fieldName = fields.next().getName();

                payload[fieldName] =
                    requestData.getValue(fieldName) || '';
            }

            payload.description =
                (requestData.getValue('description') || '') +
                ' The Update Set was originally created by ' +
                (requestData.getValue('sys_created_by') || '') +
                '.';

            payload.sys_created_by = 'Auto Deployer';
            payload.customer_updates = [];

            var customerUpdate =
                new GlideRecord('sys_update_xml');

            customerUpdate.addQuery(
                'update_set',
                localUpdateSet
            );

            customerUpdate.query();

            while (customerUpdate.next()) {
                var customer = {};

                var customerFields =
                    customerUpdate.getFields().iterator();

                while (customerFields.hasNext()) {
                    var customerFieldName =
                        customerFields.next().getName();

                    customer[customerFieldName] =
                        customerUpdate.getValue(
                            customerFieldName
                        ) || '';
                }

                payload.customer_updates.push(customer);
            }

            payload.customer_update_count =
                payload.customer_updates.length;

            var jsonPayload =
                JSON.stringify(payload, null, 2);

            gs.info('Request ' + jsonPayload);

            try {
                var restMessage =
                    new sn_ws.RESTMessageV2();

                restMessage.setEndpoint(
                    TARGET_INSTANCE_URL +
                    TARGET_API_PATH
                );

                restMessage.setHttpMethod('post');

                restMessage.setBasicAuth(
                    TARGET_USERNAME,
                    TARGET_PASSWORD
                );

                restMessage.setRequestHeader(
                    'Content-Type',
                    'application/json'
                );

                restMessage.setRequestHeader(
                    'Accept',
                    'application/json'
                );

                restMessage.setRequestBody(jsonPayload);

                var response =
                    restMessage.execute();

                var statusCode =
                    response.getStatusCode();

                var responseBody =
                    response.getBody();

                gs.info(
                    'Target HTTP Status: ' +
                    statusCode
                );

                gs.info(
                    'Target Response: ' +
                    responseBody
                );

            } catch (error) {
                gs.error(
                    'REST API call failed: ' +
                    error.message
                );
            }

        } else {
            gs.error(
                'Update Set not found: ' +
                localUpdateSet
            );
        }


