            });
            return;
        }

        var remoteSet = new GlideRecord('sys_remote_update_set');
        remoteSet.initialize();
        remoteSet.setValue('name', data.name || 'Imported Update Set');
        remoteSet.setValue('state', 'loaded');
        remoteSet.setValue('description', data.description || '');

        if (remoteSet.isValidField('application')) {
            remoteSet.setValue('application', data.application || 'global');
        }

        if (remoteSet.isValidField('remote_sys_id')) {
            remoteSet.setValue('remote_sys_id', data.sys_id || data.remote_sys_id || '');
        }

        var remoteSetId = remoteSet.insert();

        if (!remoteSetId) {
            throw new Error('Failed to create Retrieved Update Set.');
        }

        var inserted = 0;

        for (var i = 0; i < data.customer_updates.length; i++) {
