            var targetUpdate = new GlideRecord('sys_update_xml');
            targetUpdate.initialize();

            for (var fieldName in sourceUpdate) {
                if (!sourceUpdate.hasOwnProperty(fieldName)) {
                    continue;
                }

                if (fieldName == 'sys_id' || fieldName == 'update_set' || fieldName == 'remote_update_set' || fieldName == 'sys_created_on' || fieldName == 'sys_created_by' || fieldName == 'sys_updated_on' || fieldName == 'sys_updated_by' || fieldName == 'sys_mod_count') {
